// The JS selector engine (src/runtime/selectors.mjs) against the selector rows of the
// P5-cov Chrome 156 control that also gates the Rust engine:
// crates/turbo-dom/tests/fixtures/rtdom_core_chrome156.json (generated by
// scripts/rtdom-core-chrome-control.mjs; asserted for Rust by
// crates/turbo-dom/tests/rtdom_core_chrome.rs). For every selector: validity
// (querySelector throws exactly where Chrome does) and `matches` for every element —
// attribute operators, CSS comments, EOF-closed blocks and strings, escapes at EOF,
// empty items of forgiving / unforgiving lists, and the :-webkit-any() grammar
// (miaskiewicz/turbo-dom#91).
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { createEnvironment } from '../src/runtime/index.mjs';

const fixture = JSON.parse(
  readFileSync(new URL('../crates/turbo-dom/tests/fixtures/rtdom_core_chrome156.json', import.meta.url), 'utf8'),
);

// Recorded Chrome answers the JS engine does not give yet (each with its issue).
const OPEN = new Set([]);

function elements(document) {
  const out = [];
  const walk = (el) => { out.push(el); for (const c of el.children) walk(c); };
  walk(document.documentElement);
  return out;
}

const throws = (fn) => { try { fn(); return false; } catch (e) { assert.ok(e instanceof SyntaxError, String(e)); return true; } };

test('selector engine matches the P5-cov Chrome 156 selector rows (validity, matches)', () => {
  assert.ok(fixture.chrome.startsWith('156.'));
  const failures = [];
  let rows = 0;
  for (const c of fixture.selectors) {
    const { document } = createEnvironment(`<!DOCTYPE html><html><head></head><body>${c.html}</body></html>`);
    const els = elements(document);
    assert.deepEqual(els.map((e) => e.localName), c.elements, `${c.id}: element list`);
    for (const r of c.selectors) {
      rows++;
      if (OPEN.has(r.selector)) continue;
      const fail = (what) => failures.push(`${c.id} ${JSON.stringify(r.selector)}: ${what}`);
      if (throws(() => document.querySelector(r.selector)) === r.valid) {
        fail(`validity, Chrome valid=${r.valid}`);
        continue;
      }
      if (!r.valid) continue;
      const got = els.map((e) => (e.matches(r.selector) ? '1' : '0')).join('');
      if (got !== r.matches) fail(`matches ${got}, Chrome ${r.matches}`);
    }
  }
  assert.ok(rows >= 120, `fixture shrank: ${rows} rows`);
  assert.deepEqual(failures, []);
});

// miaskiewicz/turbo-dom#96: the `scope` probe replayed through the JS runtime's DOM.
test(':scope is the scoping element like Chrome 156', () => {
  const want = fixture.probes.find((p) => p.id === 'scope').values;
  const { document: doc } = createEnvironment('<!DOCTYPE html><html><head></head><body></body></html>');
  doc.body.innerHTML = '<div id=d><p id=p><span id=s></span></p><p id=q></p></div>';
  const d = doc.getElementById('d'), p = doc.getElementById('p'), s = doc.getElementById('s');
  const ids = (list) => [...list].map((e) => e.id || e.localName);
  const id = (e) => (e ? e.id || e.localName : null);
  assert.deepEqual({
    documentScope: ids(doc.querySelectorAll(':scope')),
    documentChild: ids(doc.querySelectorAll(':scope > body')),
    elementChild: ids(d.querySelectorAll(':scope > p')),
    elementSelf: ids(d.querySelectorAll(':scope')),
    elementNested: ids(d.querySelectorAll(':scope p span, :is(:scope) > p')),
    elementFirst: id(d.querySelector(':scope > p ~ p')),
    matches: [p.matches(':scope'), p.matches('div > :scope'), p.matches(':scope > span'), p.matches(':is(:scope)'), p.matches(':not(:scope)'), p.matches(':has(> :scope)'), d.matches(':has(:scope)'), d.matches(':has(> p:not(:scope))')],
    closest: [id(s.closest(':scope')), id(s.closest('div:scope')), id(s.closest(':scope span')), id(s.closest('div :scope')), id(s.closest(':not(:scope)'))],
  }, want);
});
